  ! ----------------------------------------------- !
  ! Evaluate rate coefficients                      !
  ! ----------------------------------------------- !
  subroutine get_rate_coefficients(k,M,Tloc,Ploc)
    implicit none

    real(WP), dimension(nreac + nreac_reverse) :: k
    real(WP), dimension(nFO + nFO_reverse) :: k_0
    real(WP), dimension(nFO + nFO_reverse) :: k_inf
    real(WP), dimension(nFO + nFO_reverse) :: FC
    real(WP), dimension(nTB + nFO) :: M
    real(WP) :: Tloc,Ploc,R_T_inv,T_log,redP

    ! Rate coefficients
    R_T_inv = 1.0_WP/(Rcst*Tloc)
    T_log = log(Tloc)

    k(r1f) = (1.200000e+05_WP)*exp((-1.000000e+00_WP)*T_log )
    k(r2f) = (5.000000e+05_WP)*exp((-1.000000e+00_WP)*T_log )
    k(r3f) = (3.870000e-02_WP)*exp((-2.619184e+04_WP)*R_T_inv + (2.700000e+00_WP)*T_log )
    k(r4f) = (2.000000e+07_WP)
    k(r5f) = (9.630000e+00_WP)*exp((-1.673600e+04_WP)*R_T_inv + (2.000000e+00_WP)*T_log )
    k(r6f) = (5.700000e+07_WP)
    k(r7f) = (8.000000e+07_WP)
    k(r8f) = (1.500000e+07_WP)
    k(r9f) = (1.500000e+07_WP)
    k(r10f) = (5.060000e+07_WP)
    k(r11f) = (1.020000e+03_WP)*exp((-3.598240e+04_WP)*R_T_inv + (1.500000e+00_WP)*T_log )
    k_0(FOr12f) =(6.020000e+02_WP)*exp((-1.255200e+04_WP)*R_T_inv )
    k_inf(FOr12f) =(1.800000e+04_WP)*exp((-9.978840e+03_WP)*R_T_inv )
    redP = abs(k_0(FOr12f)) * M(mM12) / max(abs(k_inf(FOr12f)), tiny(1.0_WP)) + tiny(1.0_WP)
    k(r12f) = k_inf(FOr12f) * redP / ( 1.0_WP + redP )
    k(r13f) = (3.000000e+07_WP)
    k(r14f) = (3.000000e+07_WP)
    k(r15f) = (3.900000e+07_WP)*exp((-1.481136e+04_WP)*R_T_inv )
    k(r16f) = (1.000000e+07_WP)
    k(r17f) = (1.000000e+07_WP)
    k(r18f) = (3.880000e-01_WP)*exp((-1.297040e+04_WP)*R_T_inv + (2.500000e+00_WP)*T_log )
    k(r19f) = (1.300000e-01_WP)*exp((-2.092000e+04_WP)*R_T_inv + (2.500000e+00_WP)*T_log )
    k(r20f) = (5.000000e+07_WP)
    k(r21f) = (1.350000e+01_WP)*exp((-7.949600e+03_WP)*R_T_inv + (2.000000e+00_WP)*T_log )
    k(r22f) = (4.600000e+13_WP)*exp((-1.211268e+05_WP)*R_T_inv + (-1.410000e+00_WP)*T_log )
    k(r23f) = (6.940000e+00_WP)*exp((-7.949600e+03_WP)*R_T_inv + (2.000000e+00_WP)*T_log )
    k(r24f) = (3.000000e+07_WP)
    k(r25f) = (1.250000e+01_WP)*exp((-9.204800e+02_WP)*R_T_inv + (1.830000e+00_WP)*T_log )
    k(r26f) = (2.240000e+07_WP)
    k(r27f) = (8.980000e+01_WP)*exp((-2.380696e+04_WP)*R_T_inv + (1.920000e+00_WP)*T_log )
    k(r28f) = (1.000000e+08_WP)
    k(r29f) = (1.000000e+07_WP)*exp((-3.347200e+04_WP)*R_T_inv )
    k(r30f) = (1.750000e+06_WP)*exp((-5.648400e+03_WP)*R_T_inv )
    k(r31f) = (2.500000e+06_WP)*exp((-1.999952e+05_WP)*R_T_inv )
