    k(r33f) = (2.800000e+06_WP)*exp((-8.600000e-01_WP)*T_log )
    k(r34f) = (2.080000e+07_WP)*exp((-1.240000e+00_WP)*T_log )
    k(r35f) = (1.126000e+07_WP)*exp((-7.600000e-01_WP)*T_log )
    k(r36f) = (2.600000e+07_WP)*exp((-1.240000e+00_WP)*T_log )
    k(r37f) = (7.000000e+05_WP)*exp((-8.000000e-01_WP)*T_log )
