    k(r44f) = (3.970000e+06_WP)*exp((-2.807464e+03_WP)*R_T_inv )
    k(r45f) = (4.480000e+07_WP)*exp((-4.468512e+03_WP)*R_T_inv )
    k(r46f) = (8.400000e+07_WP)*exp((-2.656840e+03_WP)*R_T_inv )
    k(r47f) = (1.210000e+01_WP)*exp((-2.175680e+04_WP)*R_T_inv + (2.000000e+00_WP)*T_log )
    k(r48f) = (1.000000e+07_WP)*exp((-1.506240e+04_WP)*R_T_inv )
    k(r49f) = (1.650000e+08_WP)
    k_0(FOr50f) =(1.040000e+14_WP)*exp((-6.694400e+03_WP)*R_T_inv + (-2.760000e+00_WP)*T_log )
    k_inf(FOr50f) =(6.000000e+08_WP)
    FC(FOr50f) = ((1.0_WP - 5.620000e-01_WP)*exp(-Tloc/(9.100000e+01_WP)) + (5.620000e-01_WP)*exp(-Tloc/(5.836000e+03_WP)))&
              + exp(-(8.552000e+03_WP)/Tloc)
    k(r50f) = getlindratecoeff(Tloc, k_0(FOr50f), k_inf(FOr50f),FC(FOr50f), M(mM50),Ploc)
