              + exp(-(6.570000e+03_WP)/Tloc)
    k(r54f) = getlindratecoeff(Tloc, k_0(FOr54f), k_inf(FOr54f),FC(FOr54f), M(mM54),Ploc)
    k(r55f) = (7.340000e+07_WP)
    k_0(FOr56f) =(1.270000e+20_WP)*exp((-2.732152e+04_WP)*R_T_inv + (-4.820000e+00_WP)*T_log )
