    FC(FOr56f) = ((1.0_WP - 7.187000e-01_WP)*exp(-Tloc/(1.030000e+02_WP)) + (7.187000e-01_WP)*exp(-Tloc/(1.291000e+03_WP)))&
              + exp(-(4.160000e+03_WP)/Tloc)
    k(r56f) = getlindratecoeff(Tloc, k_0(FOr56f), k_inf(FOr56f),FC(FOr56f), M(mM56),Ploc)
    k_0(FOr57f) =(2.200000e+18_WP)*exp((-2.326304e+04_WP)*R_T_inv + (-4.800000e+00_WP)*T_log )
    k_inf(FOr57f) =(5.400000e+05_WP)*exp((-1.087840e+04_WP)*R_T_inv + (4.540000e-01_WP)*T_log )
    FC(FOr57f) = ((1.0_WP - 7.580000e-01_WP)*exp(-Tloc/(9.400000e+01_WP)) + (7.580000e-01_WP)*exp(-Tloc/(1.555000e+03_WP)))&
              + exp(-(4.200000e+03_WP)/Tloc)
    k(r57f) = getlindratecoeff(Tloc, k_0(FOr57f), k_inf(FOr57f),FC(FOr57f), M(mM57),Ploc)
    k(r58f) = (5.740000e+01_WP)*exp((-1.147253e+04_WP)*R_T_inv + (1.900000e+00_WP)*T_log )
    k_0(FOr59f) =(4.360000e+19_WP)*exp((-2.125472e+04_WP)*R_T_inv + (-4.650000e+00_WP)*T_log )
    k_inf(FOr59f) =(1.055000e+06_WP)*exp((-3.598240e+02_WP)*R_T_inv + (5.000000e-01_WP)*T_log )
    FC(FOr59f) = ((1.0_WP - 6.000000e-01_WP)*exp(-Tloc/(1.000000e+02_WP)) + (6.000000e-01_WP)*exp(-Tloc/(9.000000e+04_WP)))&
              + exp(-(1.000000e+04_WP)/Tloc)
    k(r59f) = getlindratecoeff(Tloc, k_0(FOr59f), k_inf(FOr59f),FC(FOr59f), M(mM59),Ploc)
    k(r60f) = (2.000000e+07_WP)
    k(r61f) = (1.650000e+05_WP)*exp((1.188256e+03_WP)*R_T_inv + (6.500000e-01_WP)*T_log )
    k(r62f) = (3.280000e+07_WP)*exp((-2.552240e+03_WP)*R_T_inv + (-9.000000e-02_WP)*T_log )
    k_0(FOr63f) =(4.660000e+29_WP)*exp((-5.891072e+04_WP)*R_T_inv + (-7.440000e+00_WP)*T_log )
    k_inf(FOr63f) =(2.430000e+06_WP)*exp((-2.092000e+02_WP)*R_T_inv + (5.150000e-01_WP)*T_log )
    FC(FOr63f) = ((1.0_WP - 7.000000e-01_WP)*exp(-Tloc/(1.000000e+02_WP)) + (7.000000e-01_WP)*exp(-Tloc/(9.000000e+04_WP)))&
              + exp(-(1.000000e+04_WP)/Tloc)
    k(r63f) = getlindratecoeff(Tloc, k_0(FOr63f), k_inf(FOr63f),FC(FOr63f), M(mM63),Ploc)
    k(r64f) = (4.150000e+01_WP)*exp((-8.050016e+03_WP)*R_T_inv + (1.630000e+00_WP)*T_log )
