    k(r66f) = (1.500000e+06_WP)*exp((4.602400e+02_WP)*R_T_inv + (5.000000e-01_WP)*T_log )
    k(r67f) = (2.620000e+08_WP)*exp((-4.476880e+03_WP)*R_T_inv + (-2.300000e-01_WP)*T_log )
    k(r68f) = (1.700000e+01_WP)*exp((-2.037608e+04_WP)*R_T_inv + (2.100000e+00_WP)*T_log )
    k(r69f) = (4.200000e+00_WP)*exp((-2.037608e+04_WP)*R_T_inv + (2.100000e+00_WP)*T_log )
    k_0(FOr70f) =(3.750000e+21_WP)*exp((-7.949600e+03_WP)*R_T_inv + (-4.800000e+00_WP)*T_log )
    k_inf(FOr70f) =(1.000000e+11_WP)*exp((-1.000000e+00_WP)*T_log )
    FC(FOr70f) = ((1.0_WP - 6.464000e-01_WP)*exp(-Tloc/(1.320000e+02_WP)) + (6.464000e-01_WP)*exp(-Tloc/(1.315000e+03_WP)))&
              + exp(-(5.566000e+03_WP)/Tloc)
    k(r70f) = getlindratecoeff(Tloc, k_0(FOr70f), k_inf(FOr70f),FC(FOr70f), M(mM70),Ploc)
    k_0(FOr71f) =(3.800000e+28_WP)*exp((-3.020848e+04_WP)*R_T_inv + (-7.270000e+00_WP)*T_log )
    k_inf(FOr71f) =(5.600000e+06_WP)*exp((-1.004160e+04_WP)*R_T_inv )
    FC(FOr71f) = ((1.0_WP - 7.507000e-01_WP)*exp(-Tloc/(9.850000e+01_WP)) + (7.507000e-01_WP)*exp(-Tloc/(1.302000e+03_WP)))&
              + exp(-(4.167000e+03_WP)/Tloc)
    k(r71f) = getlindratecoeff(Tloc, k_0(FOr71f), k_inf(FOr71f),FC(FOr71f), M(mM71),Ploc)
