! ================= !
! Export thermodata !
! ================= !
subroutine pdf_mech_get_thermodata(h,cp,T)
  use pdf_mech
  implicit none

  real(WP), dimension(nspec) :: h,Cp
  real(WP) :: T
  
  ! Calculate correct values from T
  call pdf_mech_thermodata(T)

  ! Export h and Cp arrays
  h = hsp
  Cp = Cpsp

  return
end subroutine pdf_mech_get_thermodata

